(5452569, 784117, 76335, '<td valign="top">Not bad at all. He''s very confined by the frame which gives the viewer no alternative but to consider his predicament. Maybe a tad too sharp, but good details anyway.</td>', 'Not bad at all. He''s very confined by the frame which gives the viewer no alternative but to consider his predicament. Maybe a tad too sharp, but good details anyway.', '2009-04-26 10:47:29.000000', NULL, 1),
(5452570, 784444, 76335, '<td valign="top">An intersting street shot and the elements are nicely composed. Wish it were brighter.</td>', 'An intersting street shot and the elements are nicely composed. Wish it were brighter.', '2009-04-26 10:48:11.000000', NULL, 1),
(5452571, 784298, 76335, '<td valign="top">Not sure where you''re going with the title and presentation of this. Okay, you can photograph him without being seen, but to what purpose? He''s not really doing anything interesting. Even if he were facing the camera a little bit, it would be an improvement. I do like the lighting however.</td>', 'Not sure where you''re going with the title and presentation of this. Okay, you can photograph him without being seen, but to what purpose? He''s not really doing anything interesting. Even if he were facing the camera a little bit, it would be an improvement. I do like the lighting however.', '2009-04-26 10:50:35.000000', NULL, 1),
(5452572, 784220, 76335, '<td valign="top">Good candid shot, but not terribly interesting.</td>', 'Good candid shot, but not terribly interesting.', '2009-04-26 10:51:00.000000', NULL, 1),
(5452573, 783417, 76335, '<td valign="top">Good sense of scale. They stand (or sit) in stark contrast to the towering trees.</td>', 'Good sense of scale. They stand (or sit) in stark contrast to the towering trees.', '2009-04-26 10:51:45.000000', NULL, 1),
(5452574, 784319, 76335, '<td valign="top">The DOF suggests that the kid in the air is going to land on the kid in the water. Good candid moment of kids in play...</td>', 'The DOF suggests that the kid in the air is going to land on the kid in the water. Good candid moment of kids in play...', '2009-04-26 10:54:03.000000', NULL, 1),
(5452575, 784288, 76335, '<td valign="top">Nice angle; maybe a little too candid in that we can''t see her face.</td>', 'Nice angle; maybe a little too candid in that we can''t see her face.', '2009-04-26 10:54:26.000000', NULL, 1),
(5452576, 783040, 76335, '<td valign="top">Interesting expression. Were you hiding in the tree?</td>', 'Interesting expression. Were you hiding in the tree?', '2009-04-26 10:55:11.000000', NULL, 1),
(5452578, 783977, 76335, '<td valign="top">Could be interesting, but this strikes me as either a severe telephoto in poor lighting or a severe crop. The resolution just isn''t there.</td>', 'Could be interesting, but this strikes me as either a severe telephoto in poor lighting or a severe crop. The resolution just isn''t there.', '2009-04-26 10:56:26.000000', NULL, 1),
(5452579, 784255, 76335, '<td valign="top">Candid, but not much of interest to see. Even a bit more of his surroundings would have helped.</td>', 'Candid, but not much of interest to see. Even a bit more of his surroundings would have helped.', '2009-04-26 10:57:07.000000', NULL, 1),
(5452580, 783231, 76335, '<td valign="top">Kind of funky. It''s growing on me.</td>', 'Kind of funky. It''s growing on me.', '2009-04-26 10:57:41.000000', NULL, 1),
(5452581, 783729, 76335, '<td valign="top">I wouldn''t have gotten that without the title. Either way, it''s not interesting subject matter.</td>', 'I wouldn''t have gotten that without the title. Either way, it''s not interesting subject matter.', '2009-04-26 10:58:24.000000', NULL, 1),
(5452652, 783852, 106288, '<td valign="top">it looks like the water is moving. amazing</td>', 'it looks like the water is moving. amazing', '2009-04-26 13:52:13.000000', NULL, 1),
(5452926, 784421, 87252, '<td valign="top">Great tones - lovely centralised composition. The branch across the photographer''s face is mildly distracting and will probably bring your score down a bit but I really like this nonetheless.</td>', 'Great tones - lovely centralised composition. The branch across the photographer''s face is mildly distracting and will probably bring your score down a bit but I really like this nonetheless.', '2009-04-26 20:10:07.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5452928, 784116, 87252, '<td valign="top">Sweet shot - I find the think border a bit over the top though - more picture less black!</td>', 'Sweet shot - I find the think border a bit over the top though - more picture less black!', '2009-04-26 20:10:50.000000', NULL, 1),
(5452932, 784195, 87252, '<td valign="top">I love the colour cast in this, reminiscent of old style film shots. This photo is still very effective despite the child''s face being out of focus as the bokeh in his eyes really grabs your attention.</td>', 'I love the colour cast in this, reminiscent of old style film shots. This photo is still very effective despite the child''s face being out of focus as the bokeh in his eyes really grabs your attention.', '2009-04-26 20:12:54.000000', NULL, 1),
(5452933, 784255, 87252, '<td valign="top">Nice evocative shot - well done capturing the motion. I would have liked to see the whole of the bike!</td>', 'Nice evocative shot - well done capturing the motion. I would have liked to see the whole of the bike!', '2009-04-26 20:13:58.000000', NULL, 1),
(5452939, 783522, 87252, '<td valign="top">A risky entry - as an animal is unaware of the concept of photography does the idea of a "candid" moment exist to them? IMO this is a bit of a stretch of the imagination - and typically DPC doesn''t respond well to stretching! A sweet moment though, I would suggest composing the whole of the primate''s hand into the shot next time.</td>', 'A risky entry - as an animal is unaware of the concept of photography does the idea of a "candid" moment exist to them? IMO this is a bit of a stretch of the imagination - and typically DPC doesn''t respond well to stretching! A sweet moment though, I would suggest composing the whole of the primate''s hand into the shot next time.', '2009-04-26 20:18:24.000000', NULL, 1),
(5452941, 784215, 87252, '<td valign="top">This seems slightly over saturated to me, the man has quite an orange cast to him. Also i''m not sure if this is using the maximum pixel allowance, the frame seems quite small to me.</td>', 'This seems slightly over saturated to me, the man has quite an orange cast to him. Also i''m not sure if this is using the maximum pixel allowance, the frame seems quite small to me.', '2009-04-26 20:20:21.000000', NULL, 1),
(5452942, 783827, 87252, '<td valign="top">Great shot - love the negative space.</td>', 'Great shot - love the negative space.', '2009-04-26 20:20:49.000000', NULL, 1),
(5452943, 782865, 87252, '<td valign="top">Sweet shot - I would suggest a tighter crop on the father and daughter''s faces, I feel like there is too much negative space to the right of the shot.</td>', 'Sweet shot - I would suggest a tighter crop on the father and daughter''s faces, I feel like there is too much negative space to the right of the shot.', '2009-04-26 20:22:07.000000', NULL, 1),
(5452947, 784399, 87252, '<td valign="top">There is a nice sense of motion here, the wind buffeting the umbrella and the boy''s hair works well with the motion blur from panning slightly. I think this could be improved be ensuring the boy''s feet are fully in the frame, other than that this is a solid entry.</td>', 'There is a nice sense of motion here, the wind buffeting the umbrella and the boy''s hair works well with the motion blur from panning slightly. I think this could be improved be ensuring the boy''s feet are fully in the frame, other than that this is a solid entry.', '2009-04-26 20:24:32.000000', NULL, 1),
(5452950, 784389, 87252, '<td valign="top">The boy''s face is nicely lit by the nintendo screen - and the black and white conversion does a good job of covering any potential colour cast. I like the composition, the eye is naturally drawn from the boy''s eye to the nintendo, and there is nothing distracting in the background. For the purpose of challenge entries I would suggest investing in some noise reduction software (neat image or noise ninja) - although it doesn''t bother me and I think it adds to the shot in this case, you will be marked down for noisy images.</td>', 'The boy''s face is nicely lit by the nintendo screen - and the black and white conversion does a good job of covering any potential colour cast. I like the composition, the eye is naturally drawn from the boy''s eye to the nintendo, and there is nothing distracting in the background. For the purpose of challenge entries I would suggest investing in some noise reduction software (neat image or noise ninja) - although it doesn''t bother me and I think it adds to the shot in this case, you will be marked down for noisy images.', '2009-04-26 20:28:38.000000', NULL, 1),
(5452951, 784220, 87252, '<td valign="top">Good background, nice uncomplicated greys. The composition here is good apart from cutting off the bottom of the subject''s arm slightly.</td>', 'Good background, nice uncomplicated greys. The composition here is good apart from cutting off the bottom of the subject''s arm slightly.', '2009-04-26 20:30:21.000000', NULL, 1),
(5453038, 784158, 90892, '<td valign="top">I like the way the subjects stand out against the blurry background. <br/> <br/>My daughter likes the way it looks like an old time photo but its in color</td>', 'I like the way the subjects stand out against the blurry background.  My daughter likes the way it looks like an old time photo but its in color', '2009-04-26 22:24:41.000000', NULL, 1),
(5453039, 784213, 90892, '<td valign="top">interesting, certainly candid.<br/> <br/>my daughter says she likes the way it makes the subjects seem to glow.</td>', 'interesting, certainly candid. my daughter says she likes the way it makes the subjects seem to glow.', '2009-04-26 22:26:46.000000', NULL, 1),
(5453043, 784013, 90892, '<td valign="top">I love the way the colorful happy meal box and the baloons pop off the screen at you while the rest of the picture is kind of muted. I can think up a whole story to go with this picture which must mean that it is pretty darn good.</td>', 'I love the way the colorful happy meal box and the baloons pop off the screen at you while the rest of the picture is kind of muted. I can think up a whole story to go with this picture which must mean that it is pretty darn good.', '2009-04-26 22:30:06.000000', NULL, 1),
(5453044, 784015, 90892, '<td valign="top">blurry and small... interesting subject and decent composition.</td>', 'blurry and small... interesting subject and decent composition.', '2009-04-26 22:32:10.000000', NULL, 1),
(5453045, 784369, 90892, '<td valign="top">Not sure who is the subject. He is more in focus but her blurry not so candid face grabs the attention.</td>', 'Not sure who is the subject. He is more in focus but her blurry not so candid face grabs the attention.', '2009-04-26 22:34:29.000000', NULL, 1),
(5453046, 783060, 90892, '<td valign="top">I like the use of b&amp;w here and the angle.</td>', 'I like the use of b&w here and the angle.', '2009-04-26 22:36:03.000000', NULL, 1),
(5453047, 784449, 90892, '<td valign="top">everything looks great but the blown out portion of the hat.</td>', 'everything looks great but the blown out portion of the hat.', '2009-04-26 22:37:55.000000', NULL, 1),
(5453048, 784407, 90892, '<td valign="top">the background looks to be in slightly sharper focus than the subject.</td>', 'the background looks to be in slightly sharper focus than the subject.', '2009-04-26 22:39:25.000000', NULL, 1),
(5453157, 783570, 96915, '<td valign="top">Call me traditional, but I don''t consider this to be a candid, as my idea of the genre is that it should include people.</td>', 'Call me traditional, but I don''t consider this to be a candid, as my idea of the genre is that it should include people.', '2009-04-27 00:08:15.000000', NULL, 1),
(5453158, 783422, 96915, '<td valign="top">Call me traditional, but I don''t consider this to be a candid, as my idea of the genre is that it should include people.</td>', 'Call me traditional, but I don''t consider this to be a candid, as my idea of the genre is that it should include people.', '2009-04-27 00:08:23.000000', NULL, 1),
(5453160, 784213, 96915, '<td valign="top">It''s perhaps a nice moment, but to me the processing takes away from that moment.</td>', 'It''s perhaps a nice moment, but to me the processing takes away from that moment.', '2009-04-27 00:08:56.000000', NULL, 1),
(5453161, 783868, 96915, '<td valign="top">Call me traditional, but I don''t consider this to be a candid, as my idea of the genre is that it should include people.</td>', 'Call me traditional, but I don''t consider this to be a candid, as my idea of the genre is that it should include people.', '2009-04-27 00:09:04.000000', NULL, 1),
(5453165, 783928, 96915, '<td valign="top">Great silhouette and I love that you got the starburst without a bunch of globs of lens flare across the image.</td>', 'Great silhouette and I love that you got the starburst without a bunch of globs of lens flare across the image.', '2009-04-27 00:10:11.000000', NULL, 1),
(5453168, 784399, 96915, '<td valign="top">Good job catching the moment.  To me, this image seems a bit flat, which could have been remedied with some curves/levels adjustments.</td>', 'Good job catching the moment.  To me, this image seems a bit flat, which could have been remedied with some curves/levels adjustments.', '2009-04-27 00:11:28.000000', NULL, 1),
(5453170, 784431, 96915, '<td valign="top">Great contrast and lines.  I think you''ve captured the people well without even including faces.</td>', 'Great contrast and lines.  I think you''ve captured the people well without even including faces.', '2009-04-27 00:12:02.000000', NULL, 1),
(5453172, 783966, 96915, '<td valign="top">What great smiles!  I like that the mother is caught in a candid moment while the baby seems to be very aware of the camera.</td>', 'What great smiles!  I like that the mother is caught in a candid moment while the baby seems to be very aware of the camera.', '2009-04-27 00:12:59.000000', NULL, 1),
(5453179, 784407, 96915, '<td valign="top">Appears to meet the challenge, but lacks a certain something (oomph, impact, spark, I can''t quite put my finger on it).</td>', 'Appears to meet the challenge, but lacks a certain something (oomph, impact, spark, I can''t quite put my finger on it).', '2009-04-27 00:16:19.000000', NULL, 1),
(5453180, 784445, 96915, '<td valign="top">creative use of the window frame</td>', 'creative use of the window frame', '2009-04-27 00:16:34.000000', NULL, 1),
(5453182, 783597, 96915, '<td valign="top">The b/w conversion seems to have caused the men''s faces to blend in with the bckground.  I think I might have liked this more in color or with a different b/w conversion.</td>', 'The b/w conversion seems to have caused the men''s faces to blend in with the bckground.  I think I might have liked this more in color or with a different b/w conversion.', '2009-04-27 00:17:45.000000', NULL, 1),
(5453183, 782953, 96915, '<td valign="top">When I first read the title, I thought you were referring to one of the woman as the pig, but on second pass, I saw the.  Now I like it a bit more.  And I love the use of the mirror.</td>', 'When I first read the title, I thought you were referring to one of the woman as the pig, but on second pass, I saw the.  Now I like it a bit more.  And I love the use of the mirror.', '2009-04-27 00:19:22.000000', NULL, 1),
(5453192, 784308, 94855, '<td valign="top">maybe less building andmore person</td>', 'maybe less building andmore person', '2009-04-27 00:28:55.000000', NULL, 1),
(5453198, 784368, 94855, '<td valign="top">beautiful all partsof this pic express great stuff to me</td>', 'beautiful all partsof this pic express great stuff to me', '2009-04-27 00:31:18.000000', NULL, 1),
